const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const kīlaueaSummit = ee.Geometry.Point([-155.287, 19.421]);
  const buffer5km = kīlaueaSummit.buffer(5000); // 5 km buffer

  // Target date: July 20, 2025 at 10:44 am local (Hawaii is UTC-10)
  // Convert to UTC: 10:44 HST = 20:44 UTC
  const targetDate = '2025-07-20';
  const targetDateUtc = ee.Date('2025-07-20T20:44:00');

  // 2. Data Acquisition - Try Sentinel-5P SO2 data first
  let collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_SO2')
    .filterDate(targetDateUtc, targetDateUtc.advance(1, 'hour')) // 1-hour window
    .filterBounds(kīlaueaSummit);

  let colSize = collection.size().getInfo();
  console.log(`Initial collection size for ${targetDate}: ${colSize}`);

  // If no data, widen the time window to ±1 day
  if (colSize === 0) {
    console.log('Widening date window to ±1 day');
    collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_SO2')
      .filterDate('2025-07-19', '2025-07-21')
      .filterBounds(kīlaueaSummit);
    colSize = collection.size().getInfo();
    console.log(`Collection size after widening: ${colSize}`);
  }

  // If still no data, try previous year (2024) same date
  if (colSize === 0) {
    console.log('Trying same date in previous year (2024)');
    collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_SO2')
      .filterDate('2024-07-19', '2024-07-21')
      .filterBounds(kīlaueaSummit);
    colSize = collection.size().getInfo();
    console.log(`Collection size for 2024: ${colSize}`);
  }

  // If still empty, output C1
  if (colSize === 0) {
    console.log('No SO2 data available for analysis');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Get the closest image to target time
  const image = collection.sort('system:time_start', false).first();

  // Get SO2 column density band and apply quality mask
  const so2Band = image.select('SO2_column_number_density');
  const qaBand = image.select('qa_value');

  // Mask low quality pixels (qa_value < 0.5)
  const maskedSO2 = so2Band.updateMask(qaBand.gte(0.5));

  // Define plume threshold (0.0005 mol/m² typical for volcanic plumes)
  const plumeThreshold = 0.0005;
  const plumeMask = maskedSO2.gt(plumeThreshold);

  // Count valid plume pixels
  const pixelCount = plumeMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer5km.buffer(10000), // 15 km area around summit
    scale: 1000,
    maxPixels: 1e9
  }).get('SO2_column_number_density').getInfo();

  console.log(`Valid plume pixels: ${pixelCount}`);

  // Check if we have any valid plume pixels
  if (pixelCount === 0 || pixelCount === null) {
    console.log('No valid plume pixels detected');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculate maximum distance of plume from summit
  // Create distance raster from summit
  const distanceImage = ee.Image.pixelDistance(kīlaueaSummit, 111320); // meters per degree

  // Get distance of plume pixels only
  const plumeDistance = distanceImage.updateMask(plumeMask);

  // Calculate maximum distance
  const maxDistance = plumeDistance.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: buffer5km.buffer(20000), // 25 km area
    scale: 1000,
    maxPixels: 1e9
  }).get('distance').getInfo();

  console.log(`Maximum plume distance from summit: ${maxDistance ? maxDistance.toFixed(2) : 'null'} m`);

  // 5. Validation & Final Answer
  if (maxDistance === null || maxDistance === undefined || isNaN(maxDistance)) {
    console.log('Distance calculation failed');
    console.log('<answer>C3</answer>');
  } else if (maxDistance > 5000) {
    console.log(`Plume extends ${(maxDistance/1000).toFixed(2)} km (> 5 km)`);
    console.log('<answer>A</answer>');
  } else {
    console.log(`Plume extends ${(maxDistance/1000).toFixed(2)} km (≤ 5 km)`);
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
